def payload(owner, batch_size=20):
    return {"owner": owner, "batch_size": batch_size}

def validate_batch_size(value):
    if isinstance(value, bool):
        raise ValueError("batch_size must be an integer, not a boolean")
    if not isinstance(value, int):
        raise ValueError("batch_size must be an integer")
    if value < 1 or value > 100:
        raise ValueError("batch_size must be between 1 and 100")
    return value

from queueing import payload, validate_batch_size

def submit(owner, enqueue=None, batch_size=20):
    if enqueue is None:
        raise ValueError("enqueue parameter is required")

    # Validate batch_size before enqueue (reject bool and invalid values with ValueError)
    if batch_size is not None:
        validate_batch_size(batch_size)

    return enqueue(payload(owner, batch_size))

def execute(task, process):
    owner = task.get("owner")
    batch_size = task.get("batch_size", 20)
    return process(owner, batch_size)
